def _get_event_ids_for_partial_state_join(
    join_event: EventBase,
    prev_state_ids: StateMap[str],
) -> Collection[str]:
    """Calculate state to be retuned in a partial_state send_join

    Args:
        join_event: the join event being send_joined
        prev_state_ids: the event ids of the state before the join

    Returns:
        the event ids to be returned
    """

    # return all non-member events
    state_event_ids = {
        event_id
        for (event_type, state_key), event_id in prev_state_ids.items()
        if event_type != EventTypes.Member
    }

    # we also need the current state of the current user (it's going to
    # be an auth event for the new join, so we may as well return it)
    current_membership_event_id = prev_state_ids.get(
        (EventTypes.Member, join_event.state_key)
    )
    if current_membership_event_id is not None:
        state_event_ids.add(current_membership_event_id)

    # return members with invites
    for (event_type, state_key), event_id in prev_state_ids.items():
        if event_type == EventTypes.Member and state_key != join_event.state_key:
            if prev_state_ids.get((EventTypes.Invite, state_key)) is not None:
                state_event_ids.add(event_id)

    # return members that are kicked or banned
    for (event_type, state_key), event_id in prev_state_ids.items():
        if event_type == EventTypes.Member and state_key != join_event.state_key:
            if prev_state_ids.get((EventTypes.Kick, state_key)) is not None or 
               prev_state_ids.get((EventTypes.Ban, state_key)) is not None:
                state_event_ids.add(event_id)

    return state_event_ids

def isSpreadSheetCell(self, obj, startFromTable=False):
    """Return an indication of whether the given obj is a spread sheet
    table cell.

    Arguments:
    - obj: the object to check.
    - startFromTable: if True, then the component hierarchy check should
      start from a table (as opposed to a table cell).

    Returns True if this is a table cell, False otherwise.
    """

    cell = obj
    if not startFromTable:
        obj = obj.parent

    try:
        table = obj.queryTable()
    except:
        if cell.getRole() == pyatspi.ROLE_PARAGRAPH:
            top = self.topLevelObject(cell)
            return (top and top.name.endswith(" Calc"))
        else:
            return False
    else:
        return table.nRows in [65536, 1048576]

def check_htmllinks(path):
    ddir = docdir.localpath

    for lineno, line in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                # Retrieve the URL content
                pass
            elif tryfn.endswith('.html'):
                # assume it should be a file
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail("reference error %r in %s:%d " %(
                                  tryfn, path.basename, lineno+1))
            else:
                # yes, what else?
                pass

def _retrieve(self, url):
    """Retrieve the given URL."""
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if 'Content-Type' in info_dict:
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode = ct_line[csi+9:]
                # Validate the encoding
                if not is_valid_encoding(encode):
                    encode = 'latin1'  # fallback to default encoding
        uopener.close()
        self.urlOpener.close()
    except IOError as e:
        raise IMDbDataAccessError({'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()})
    return unicode(content, encode, 'replace')

def is_valid_encoding(encoding):
    try:
        codecs.lookup(encoding)
        return True
    except LookupError:
        return False

def config_init(prompt=True):
    config_path = os.getcwd()+"/.wandb"
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style("This directory is already initialized, should we overwrite it?", fg="red"), abort=True)
    else:
        if os.path.isfile(config_path):
            os.rename(config_path, config_path.replace(".wandb", ".wandb.tmp"))
        os.mkdir(config_path)
        if os.path.isfile(config_path.replace(".wandb", ".wandb.tmp")):
            os.rename(config_path.replace(".wandb", ".wandb.tmp"), config_path.replace(".wandb.tmp", ".wandb/config"))
    config.batch_size_desc = "Number of training examples in a mini-batch"
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo("""Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:

import wandb
conf = wandb.Config()
conf.batch_size
""")

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    try:
        with open(urls_file) as file:
            for url in file:
                collect_from_url(url, archive_dir=archive_dir, notes=notes)
    except FileNotFoundError:
        print(f"Error: The file {urls_file} was not found.")
