        print(f"An error occurred while processing the file: {e}")

def finish_song_deletion(self, coresong):
    """Removes a song from the playlist

    :param CoreSong coresong: song to remove
    """
    def update_cb(conn, res):
        if res is None:
            self._log.warning("Update failed: No response received.")
            self._notificationmanager.pop_loading()
            return
        conn.update_finish(res)
        self._notificationmanager.pop_loading()

    def entry_retrieved_cb(source, op_id, media, remaining, error):
        if error:
            self._log.warning("Error: {}".format(error))
            return

        if not media:
            return

        self._notificationmanager.push_loading()
        update_query = """
        INSERT OR REPLACE {
            ?entry nfo:listPosition ?position .
        }
        WHERE {
            SELECT ?entry
                   (?old_position - 1) AS ?position
            WHERE {
                ?entry a nfo:MediaFileListEntry ;
                         nfo:listPosition ?old_position .
                ?playlist nfo:hasMediaFileListEntry ?entry .
                FILTER (?old_position > ?removed_position)
                {
                    SELECT ?playlist
                           ?removed_position
                    WHERE {
                        ?playlist a nmm:Playlist ;
                                  a nfo:MediaList ;
                                    nfo:hasMediaFileListEntry
                                    ?removed_entry .
                        ?removed_entry nfo:listPosition ?removed_position .
                        FILTER (
                            tracker:id(?playlist) = %(playlist_id)s &&
                            tracker:id(?removed_entry) = %(entry_id)s
                        )
                    }
                }
            }
        };
        INSERT OR REPLACE {
            ?playlist nfo:entryCounter ?new_counter .
        }
        WHERE {
            SELECT ?playlist
                   (?counter - 1) AS ?new_counter
            WHERE {
                ?playlist a nmm:Playlist ;
                          a nfo:MediaList ;
                            nfo:entryCounter ?counter .
                FILTER (
                    tracker:id(?playlist) = %(playlist_id)s
                )
            }
        };
        DELETE {
            ?playlist nfo:hasMediaFileListEntry ?entry .
            ?entry a rdfs:Resource .
        }
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            FILTER (
                tracker:id(?playlist) = %(playlist_id)s &&
                tracker:id(?entry) = %(entry_id)s
            )
        }
        """.replace("\n", " ").strip() % {
            "playlist_id": self.props.pl_id,
            "entry_id": media.get_id()
        }

        self._tracker.update_async(update_query, None, update_cb)

    song_id = coresong.props.media.get_id()
    entry_query = """
    SELECT
        %(media_type)s AS ?type
        ?entry AS ?id
        WHERE {
            ?playlist a nmm:Playlist ;
                      a nfo:MediaList ;
                        nfo:hasMediaFileListEntry ?entry .
            ?entry a nfo:MediaFileListEntry ;
                     nfo:entryUrl ?url .
            SERVICE <dbus:%(miner_fs_busname)s> {
                GRAPH tracker:Audio {
                    SELECT
                        ?song
                        ?url
                    WHERE {
                        ?song a nmm:MusicPiece ;
                              nie:isStoredAs ?url .
                        FILTER (
                            %(filter_clause_song)s
                        )
                    }
                }
            }
            FILTER (
                %(filter_clause_pl)s
            )
        }
    """.replace("\n", " ").strip() % {
        "media_type": int(Grl.MediaType.AUDIO),
        "filter_clause_song": "tracker:id(?song) = " + song_id,
        "filter_clause_pl": "tracker:id(?playlist) = " + self.props.pl_id,
        "miner_fs_busname": self._tracker_wrapper.props.miner_fs_busname
    }

    self._source.query(
        entry_query, [Grl.METADATA_KEY_ID], self._fast_options,
        entry_retrieved_cb)

def __parse_token(self, token):
    try:
        return jwt.decode(token, verify=False)
    except jwt.InvalidTokenError as e:
        raise ValueError('Invalid token provided') from e

def sanitize_snmp_table_columns(columns):
    endoids = []
    for fetchoid, column in columns:
        for o, value in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)

    endoids.sort(cmp = cmp_oids)

    new_columns = []
    for fetchoid, column in columns:
        if column != sorted(column, key=cmp_oid_pairs):
            column.sort(cmp = cmp_oid_pairs)

        i = 0
        new_column = []
        for o, value in column:
            eo = extract_end_oid(fetchoid, o)
            if len(column) != len(endoids):
                while i < len(endoids) and endoids[i] != eo:
                    new_column.append("")
                    i += 1
            new_column.append(value)
            i += 1

        while i < len(endoids):
            new_column.append("")
            i += 1
        new_columns.append(new_column)

    return new_columns

def _name2(self, v, current_klass, attr_name):
    obj = v.name

    if obj in self.method_imported_globals:
        call_name = UU+self.modpfx() + obj + "." + attr_name
    elif self.imported_classes.has_key(obj):
        attr_str = ".prototype.__class__." + attr_name
        call_name = UU+self.imported_classes[obj] + '.__' + obj + attr_str
    elif obj in self.module_imports():
        call_name = obj + "." + attr_name
    else:
        call_name = UU+self._name(v, current_klass) + "." + attr_name

    return call_name

def replace(var, wrapper, message):
    """Swap out a player logged in to your account."""
    if wrapper.source not in channels.Main.users:
        wrapper.pm(messages["invalid_channel"].format(channels.Main))
        return

    if wrapper.source in get_players():
        wrapper.pm(messages["already_playing"].format("You"))
        return

    if wrapper.source.account is None:
        wrapper.pm(messages["not_logged_in"])
        return

    rest = message.split()

    if not rest: # bare call
        target = None

        for user in var.ALL_PLAYERS:
            if users.equals(user.account, wrapper.source.account):
                if user is wrapper.source or user not in get_participants():
                    continue
                elif target is None:
                    target = user
                else:
                    wrapper.pm(messages["swap_notice"].format(botconfig.CMD_CHAR))
                    return

        if target is None:
            wrapper.pm(messages["account_not_playing"])
            return

    else:
        pl = get_participants()

        target, _ = users.complete_match(rest[0], pl)

        if target is None:
            wrapper.pm(messages["target_not_playing"])
            return

        if target not in pl:
            wrapper.pm(messages["target_no_longer_playing" if target.nick in var.DEAD else "target_not_playing"])
            return

        if target.account is None:
            wrapper.pm(messages["target_not_logged_in"])
            return

    if users.equals(target.account, wrapper.source.account) and target is not wrapper.source:
        rename_player(var, wrapper.source, target.nick)
        target.swap(wrapper.source)
        if var.PHASE in var.GAME_PHASES:
            return_to_village(var, target, show_message=False)

        if not var.DEVOICE_DURING_NIGHT or var.PHASE != "night":
            channels.Main.mode(("-v", target), ("+v", wrapper.source))

        channels.Main.send(messages["player_swap"].format(wrapper.source, target))
        if var.PHASE in var.GAME_PHASES:
            myrole.func(var, wrapper, "")

def decode_batch(self, window, location):
    n_samples = location.shape[0]

    for batch_id in range(n_samples):
        image_id = location[batch_id, 0]
        if image_id != self.current_id:
            if self.image_out is not None:
                self._save_image()
            self.current_id = image_id
            self.image_out = self._create_empty_image(window.shape)
        self.image_out[...] = window
    import pdb; pdb.set_trace()
    return

