def __init__(self, version: int = MAX_TEAL_VERSION):
    self.teal_version = version

    self.attrs = {
        m: (getattr(self, m), getattr_static(self, m))
        for m in list(set(dir(self.__class__)) - set(dir(super())))
        if not m.startswith("__")
    }

    self.hints: dict[str, MethodHints] = {}
    self.bare_handlers: dict[str, OnCompleteAction] = {}
    self.methods: dict[str, tuple[ABIReturnSubroutine, MethodConfig]] = {}

    acct_vals: dict[str, AccountStateValue | DynamicAccountStateValue] = {}
    app_vals: dict[str, ApplicationStateValue | DynamicApplicationStateValue] = {}

    for name, (bound_attr, static_attr) in self.attrs.items():

        # Check for state vals
        match bound_attr:
            case AccountStateValue():
                if bound_attr.key is None:
                    bound_attr.key = Bytes(name)
                acct_vals[name] = bound_attr
            case DynamicAccountStateValue():
                acct_vals[name] = bound_attr
            case ApplicationStateValue():
                if bound_attr.key is None:
                    bound_attr.key = Bytes(name)
                app_vals[name] = bound_attr
            case DynamicApplicationStateValue():
                app_vals[name] = bound_attr

        if name in app_vals or name in acct_vals:
            continue

        # Check for handlers and internal methods
        handler_config = get_handler_config(bound_attr)
        match handler_config:
            # Bare Handlers
            case HandlerConfig(bare_method=BareCallActions()):
                actions = {
                    oc: cast(OnCompleteAction, action)
                    for oc, action in handler_config.bare_method.__dict__.items()
                    if action is not None
                }

                for oc, action in actions.items():
                    if oc in self.bare_handlers:
                        raise BareOverwriteError(oc)

                    # Swap the implementation with the bound version
                    if handler_config.referenced_self:
                        action.action.subroutine.implementation = bound_attr

                    self.bare_handlers[oc] = action

            # ABI Methods
            case HandlerConfig(method_spec=Method()):
                # Create the ABIReturnSubroutine from the static attr
                # but override the implementation with the bound version
                abi_meth = ABIReturnSubroutine(static_attr)
                if handler_config.referenced_self:
                    abi_meth.subroutine.implementation = bound_attr
                self.methods[name] = abi_meth

                self.hints[name] = handler_config.hints()

            # Internal subroutines
            case HandlerConfig(subroutine=Subroutine()):
                if handler_config.referenced_self:
                    setattr(self, name, handler_config.subroutine(bound_attr))
                else:
                    setattr(
                        self.__class__,
                        name,
                        handler_config.subroutine(static_attr),
                    )

    self.acct_state = AccountState(acct_vals)
    self.app_state = ApplicationState(app_vals)

    # Create router with name of class and bare handlers
    self.router = Router(
        name=self.__class__.__name__,
        bare_calls=BareCallActions(**self.bare_handlers),
    )

    # Add method handlers
    for method in self.methods.values():
        self.router.add_method_handler(
            method_call=method, method_config=handler_config.method_config
        )

    (
        self.approval_program,
        self.clear_program,
        self.contract,
    ) = self.router.compile_program(
        version=self.teal_version,
        assemble_constants=True,
        optimize=OptimizeOptions(scratch_slots=True),
    )

def process_view(self, request, view_func, view_args, view_kwargs):

    if hasattr(request, 'user') and toggle.shortcuts.toggle_enabled(toggles.PRBAC_DEMO, request.user.username):
        role_slug = request.GET.get('role', 'community_plan_v0')
        request.role = Role.objects.get(slug=role_slug)
        return None

    if hasattr(request, 'domain'):
        request.role = accounting.role_for_domain(request.domain)
    else:
        request.role = Role()  # A fresh Role() has no privileges

    return None

def save_problem(self, get):
    '''
    Save the passed in answers.
    Returns a dict { 'success' : bool, ['error' : error-msg]},
    with the error key only present if success is False.
    '''
    event_info = dict()
    event_info['state'] = self.lcp.get_state()
    event_info['problem_id'] = self.location.url()

    answers = self.make_dict_of_responses(get)
    event_info['answers'] = answers

    # Too late. Cannot submit
    if self.closed():
        event_info['failure'] = 'closed'
        self.system.track_function('save_problem_fail', event_info)
        return {'success': False,
                'error': "Problem is closed"}

    # Problem submitted. Student should reset before saving
    # again.
    if self.lcp.done and self.rerandomize == "always":
        event_info['failure'] = 'done'
        self.system.track_function('save_problem_fail', event_info)
        return {'success': False,
                'error': "Problem needs to be reset prior to save."}

    self.lcp.student_answers = answers

    return {'success': True}

def get_unhosted_gateways(self, port_physnet_dict, chassis_physnets,
                          gw_chassis):
    unhosted_gateways = []
    for lrp in self._tables['Logical_Router_Port'].rows.values():
        if not lrp.name.startswith('lrp-'):
            continue
        physnet = port_physnet_dict.get(lrp.name[len('lrp-'):])
        chassis_list = self._get_logical_router_port_gateway_chassis(lrp)
        is_max_gw_reached = len(chassis_list) < ovn_const.MAX_GW_CHASSIS
        for chassis_name, prio in chassis_list:
            if is_max_gw_reached or utils.is_gateway_chassis_invalid(
                    chassis_name, gw_chassis, physnet, chassis_physnets):
                unhosted_gateways.append(lrp.name)
            else:
                # Handle the case when a chassis is no longer valid
                # This may involve moving conntrack states,
                # so it needs to discussed in the OVN community first.
                pass
    return unhosted_gateways

def export_svg(self) -> None:
    path, _ = QtWidgets.QFileDialog.getSaveFileName(
        self,
        caption="Save SVG File",
        filter="SVG Files (*.svg)",
    )
    if not path:
        return
    try:
        t0 = time.perf_counter()
        with open(path, "wt") as fp:
            fp.write(self.make_svg_string())
        self.show_message(
            f"SVG successfully in {time.perf_counter()-t0:.2f}s exported"
        )
    except IOError as e:
        self.show_message(str(e))

def test_json_encode_decode(self):
    op_meta_info = OpMetaInfo('x.y.Z')
    op_meta_info.header['description'] = 'Hello!'
    op_meta_info.input['x'] = {'data_type': str}
    op_meta_info.input['y'] = {'data_type': int}
    op_meta_info.output[RETURN] = {'data_type': str}

    s = op_meta_info.to_json()
    d1 = json.loads(s)

    self.assertEqual(d1['qualified_name'], op_meta_info.qualified_name)
    self.assertEqual(d1['header'], op_meta_info.header)
    self.assertEqual(d1['input'], io_def_namespace_to_dict(op_meta_info.input))
    self.assertEqual(d1['output'], io_def_namespace_to_dict(op_meta_info.output))

def copy_worker(event, lambda_context):
    """This is what actually does the work of copying the files."""
    class CopyWorkerTimedThread(TimedThread[dict]):
        def __init__(self, timeout_seconds: float, state: dict) -> None:
            super().__init__(timeout_seconds, state)
            self.gcp_client = Config.get_native_handle(Replica.gcp)

            self.source_bucket = state[Key.SOURCE_BUCKET]
            self.source_key = state[Key.SOURCE_KEY]
            self.source_crc32c = state[_Key.SOURCE_CRC32C]
            self.destination_bucket = state[Key.DESTINATION_BUCKET]
            self.destination_key = state[Key.DESTINATION_KEY]
            self.size = state[_Key.SIZE]

        def run(self) -> dict:
            state = self.get_state_copy()
            src_blob = self.gcp_client.bucket(self.source_bucket).get_blob(self.source_key)
            dst_blob = self.gcp_client.bucket(self.destination_bucket).blob(self.destination_key)
            content_type = src_blob.content_type or "application/octet-stream"

            will_cache = should_cache_file(content_type, self.size)
            if not will_cache:
                logger.info("Not caching %s with content-type %s size %s", self.source_key, content_type, self.size)

            if not will_cache and is_dss_bucket(self.destination_bucket):
                # Removed DURABLE_REDUCED_AVAILABILITY storage class usage
                dst_blob._patch_property('contentType', content_type)

            while True:
                response = dst_blob.rewrite(src_blob, token=state.get(_Key.TOKEN, None))
                if response[0] is None:
                    state[Key.FINISHED] = True
                    return state
                else:
                    state[_Key.TOKEN] = response[0]
                    self.save_state(state)

    return CopyWorkerTimedThread(lambda_context.get_remaining_time_in_millis() / 1000 - 10, event).start()

def reshape(ctx: LoweringRuleContext, op, aval_out: core.AbstractValue) -> ir.Value:
  if dtypes.is_opaque_dtype(aval_out.dtype):  # type: ignore
    aval_out, = aval_out.dtype._rules.physical_avals(aval_out)  # type: ignore
  if not core.is_constant_shape(aval_out.shape):  # type: ignore
    shape = eval_dynamic_shape(ctx, aval_out.shape)  # type: ignore
    return hlo.DynamicReshapeOp(
        aval_to_ir_type(aval_out), op,
        shape_tensor(shape),
    ).result
  else:
    return hlo.ReshapeOp(aval_to_ir_type(aval_out), op).result

def get_github_pull_from_sha(g, repo, installation_id, installation_token,
                             sha):

    issues = list(g.search_issues("repo:%s is:pr is:open %s" %
                                  (repo.full_name, sha)))
    if not issues:
        return
    if len(issues) > 1:  # pragma: no cover
        # NOTE(sileht): It's that technically possible, but really ?
        LOG.warning("sha attached to multiple pull requests", sha=sha)
    for i in issues:
        try:
            pull = repo.get_pull(i.number)
        except github.GithubException as e:  # pragma: no cover
            if e.status != 404:
                raise
        if pull and not pull.merged:
            return pull

def create_sync_schedule(self, repo_id, importer_id, sync_options, schedule_data):
    """
    Create a new sync schedule for a give repository using the given importer.
    @param repo_id:
    @param importer_id:
    @param sync_options:
    @param schedule_data:
    @return:
    """

    # validate the input
    importer_manager = managers_factory.repo_importer_manager()
    importer = importer_manager.get_importer(repo_id)
    if importer_id != importer['id']:
        raise pulp_exceptions.MissingResource(importer=importer_id)
    self._validate_keys(sync_options, _SYNC_OPTION_KEYS)
    if 'schedule' not in sync_options:
        raise pulp_exceptions.MissingValue(['schedule'])

    # build the sync call request
    sync_manager = managers_factory.repo_sync_manager()
    args = [repo_id]
    kwargs = {'sync_config_override': sync_options['override_config']}
    resources = {dispatch_constants.RESOURCE_REPOSITORY_TYPE: {repo_id: dispatch_constants.RESOURCE_UPDATE_OPERATION},
                 dispatch_constants.RESOURCE_REPOSITORY_IMPORTER_TYPE: {importer_id: dispatch_constants.RESOURCE_READ_OPERATION}}
    weight = pulp_config.config.getint('tasks', 'sync_weight')
    tags = [repo_id, importer_id]
    call_request = CallRequest(sync_manager.sync, args, kwargs, resources, weight, tags, archive=True)

    # schedule the sync
    scheduler = dispatch_factory.scheduler()
    schedule_id = scheduler.add(call_request, **schedule_data)
    importer_manager.update_importer(repo_id, {'schedule_id': schedule_id})
    return schedule_id

def create(self):
    """Create a new file.
    @return The file path.
    @raise FileCreator.Error.
    """
    dir_path = self.dir_path
    if not exists(dir_path):
        try:
            os.makedirs(dir_path, 0o755)
        except os.error as e:
            if not exists(dir_path):
                logger.warning('Cannot create directory %s (%s)', dir_path, e)

                raise self.Error('The directory {} cannot be created.'.format(dir_path)) from e

    name = secure_filename(self.name)
    name_root, name_ext = splitext(name)
    current_name_root = name_root
    max_trials = self.max_trials
    max_length = self.max_length - len(name_ext)
    trials = 0

    for generator_cls in self._generators_classes:
        for suffix in generator_cls():
            trials += 1

            root_max_len = max_length - len(suffix)
            if root_max_len < 0:
                raise self.Error('No unique filename has been found with the '
                                 'current rules (max length too short for suffix alone).'
                                )

            current_name_root = name_root[:root_max_len] + suffix
            final_path = join(dir_path, current_name_root + name_ext)

            try:
                with open(final_path, 'x') as f:
                    pass
            except OSError as e:
                 if trials >= max_trials:
                    raise self.Error('No unique filename has been found with the '
                                     'current rules (max trials reached).'
                                    ) from e
            else:
                return final_path
        else:
            name_root = current_name_root  # We 'pipe' the name-generation rules.

    raise self.Error('No unique filename has been found with the current rules.')

def get_config(config_key: str):
  """Get a config given its keyed name."""
  config_map = {
      'birdnet_soundscapes': birdnet_soundscapes.get_config,
      'raw_soundscapes': raw_soundscapes.get_config,
      'separate_soundscapes': separate_soundscapes.get_config,
      'reef': reef.get_config
  }
  if config_key in config_map:
      config = config_map[config_key]()
  else:
      raise ValueError('Unknown config.')
  logging.info('Loaded config %s', config_key)
  logging.info('Config output location : %s', config.output_dir)
  return config

def _build_key(self, key, namespace=None):
    if namespace is not None:
        return "{}{}".format(namespace, key)
    if self.namespace is not None:
        return "{}{}".format(self.namespace, key)
    return key

def _modular_symbol_0_to_alpha(self, alpha, i=0):
    if alpha.is_infinity():
        return self.manin_symbol((i,0,1), check=False)
    v, c = arith.continued_fraction_list(alpha._rational_(), partial_convergents=True)
    a = self(0)
    if self.weight() > 2:
        a = self.manin_symbol((i, 0, 1), check=False)  # Apply action to the polynomial part
    for k in range(1,len(c)):
        u = c[k][1]
        v = c[k-1][1]
        if k % 2 == 0:
            v = -v
        x = self.manin_symbol((i, u, v), check=False)
        a += x
    return a

def clock_gettime(clk_id):
  if platform.system().lower() == "darwin":
    return time.time()
  else:
    t = timespec()
    if libc.clock_gettime(clk_id, ctypes.pointer(t)) != 0:
      errno_ = ctypes.get_errno()
      raise OSError(errno_, os.strerror(errno_))
    return t.tv_sec + t.tv_nsec * 1e-9

def __init__(self, environment, kwargs):
    super().__init__('boost', environment, 'cpp', kwargs)
    self.need_static_link = ['boost_exception', 'boost_test_exec_monitor']
    self.is_debug = environment.cmd_line_options.buildtype in ['debug', 'Debug']
    threading = kwargs.get("threading", "multi")
    self.is_multithreading = threading == "multi"

    self.requested_modules = self.get_requested(kwargs)

    self.boost_root = None
    self.boost_roots = []
    self.incdir = None
    self.libdir = None

    if 'BOOST_ROOT' in os.environ:
        self.boost_root = os.environ['BOOST_ROOT']
        self.boost_roots = [self.boost_root]
        if not os.path.isabs(self.boost_root):
            raise DependencyException('BOOST_ROOT must be an absolute path.')
    if 'BOOST_INCLUDEDIR' in os.environ:
        self.incdir = os.environ['BOOST_INCLUDEDIR']
    if 'BOOST_LIBRARYDIR' in os.environ:
        self.libdir = os.environ['BOOST_LIBRARYDIR']

    if self.boost_root is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.boost_roots = self.detect_win_roots()
        else:
            self.boost_roots = self.detect_nix_roots()

    if self.incdir is None:
        if mesonlib.for_windows(self.want_cross, self.env):
            self.incdir = self.detect_win_incdir()
        else:
            self.incdir = self.detect_nix_incdir()

    if self.check_invalid_modules():
        self.log_fail()
        return

    mlog.debug('Boost library root dir is', mlog.bold(self.boost_root))
    mlog.debug('Boost include directory is', mlog.bold(self.incdir))

    # 1. check if we can find BOOST headers.
    self.detect_headers_and_version()

    # 2. check if we can find BOOST libraries.
    if self.is_found:
        self.detect_lib_modules()
        mlog.debug('Boost library directory is', mlog.bold(self.libdir))

    # 3. Report success or failure
    if self.is_found:
        self.log_success()
    else:
        self.log_fail()

def __getitem__(self, item) -> Tuple[Any, Dict[int, Dict]]:
    if self._cached_state_dict is not None:
        if self.worker_id in self._cached_state_dict:
            self._cached_state_dict[self.worker_id]['rng_states'] = {}  # Reset random states
        self._cached_state_dict = None

    data = self.dataset[item]
    state_dict = self._state_dict()
    return data, state_dict

def get_selection(self):
    w = self.sequence_id
    try:
        return w.selection_get()
    except (AttributeError, ValueError):
        return ''

def _get_proxy_options(self):
    proxy_options = []
    for var in ('http', 'https'):
        proxy = os.environ.get('{}_proxy'.format(var), False)
        if proxy:
            parsed_url = urllib.parse.urlparse(proxy)
            proxy_options.append('-D{}.proxyHost={}'.format(
                var, parsed_url.hostname))
            if parsed_url.port:
                proxy_options.append(
                    '-D{}.proxyPort={}'.format(var, parsed_url.port))
            # Support for username and password
            if parsed_url.username:
                proxy_options.append('-D{}.proxyUser={}'.format(var, parsed_url.username))
            if parsed_url.password:
                proxy_options.append('-D{}.proxyPassword={}'.format(var, parsed_url.password))
    return proxy_options

def update_snapshot(self, data: bytes):
    """Verifies and loads 'data' as new snapshot metadata.

    Args:
        data: unverified new snapshot metadata as bytes

    Raises:
        RepositoryError: Metadata failed to load or verify. The actual
            error type and content will contain more details.
    """

    if self.timestamp is None:
        raise RuntimeError("Cannot update snapshot before timestamp")
    if self.targets is not None:
        raise RuntimeError("Cannot update snapshot after targets")
    logger.debug("Updating snapshot")

    meta = self.timestamp.signed.meta["snapshot.json"]

    # Verify against the hashes in timestamp, if any
    hashes = meta.hashes or {}
    for algo, stored_hash in hashes.items():
        digest_object = sslib_hash.digest(algo)
        digest_object.update(data)
        observed_hash = digest_object.hexdigest()
        if observed_hash != stored_hash:
            raise exceptions.BadHashError(stored_hash, observed_hash)

    try:
        new_snapshot = Metadata.from_bytes(data)
    except DeserializationError as e:
        raise exceptions.RepositoryError("Failed to load snapshot") from e

    if new_snapshot.signed.type != "snapshot":
        raise exceptions.RepositoryError(
            f"Expected 'snapshot', got '{new_snapshot.signed.type}'"
        )

    if not verify_with_threshold(self.root, "snapshot", new_snapshot):
        raise exceptions.UnsignedMetadataError(
            "New snapshot is not signed by root", new_snapshot.signed
        )

    if (
        new_snapshot.signed.version
        != self.timestamp.signed.meta["snapshot.json"].version
    ):
        raise exceptions.BadVersionNumberError(
            f"Expected snapshot version "
            f"{self.timestamp.signed.meta['snapshot.json'].version}, "
            f"got {new_snapshot.signed.version}"
        )

    # If an existing trusted snapshot is updated,
    # check for a rollback attack
    if self.snapshot is not None:
        for filename, fileinfo in self.snapshot.signed.meta.items():
            new_fileinfo = new_snapshot.signed.meta.get(filename)

            # Prevent removal of any metadata in meta
            if new_fileinfo is None:
                raise exceptions.RepositoryError(
                    f"New snapshot is missing info for '{filename}'"
                )

            # Prevent rollback of any metadata versions
            if new_fileinfo.version < fileinfo.version:
                raise exceptions.BadVersionNumberError(
                    f"Expected {filename} version "
                    f"{new_fileinfo.version}, got {fileinfo.version}."
                )

    if new_snapshot.signed.is_expired(self.reference_time):
        raise exceptions.ExpiredMetadataError("New snapshot is expired")

    self._trusted_set["snapshot"] = new_snapshot
    logger.debug("Updated snapshot")

def post_exec(self):
    """Turn off the INDENTITY_INSERT mode if it's been activated,
    and fetch recently inserted IDENTIFY values (works only for
    one column).
    """

    if self.compiled.isinsert:
        if self.IINSERT:
            table_name = self.compiled.statement.table.fullname
            self.cursor.execute("SET IDENTITY_INSERT [" + table_name + "] OFF")
            self.IINSERT = False
        elif self.HASIDENT:
            if not len(self._last_inserted_ids) or self._last_inserted_ids[0] is None:
                if self.dialect.use_scope_identity:
                    self.cursor.execute("SELECT scope_identity() AS lastrowid")
                else:
                    self.cursor.execute("SELECT @@identity AS lastrowid")
                row = self.cursor.fetchone()
                self._last_inserted_ids = [int(row[0])] + self._last_inserted_ids[1:]
                # print "LAST ROW ID", self._last_inserted_ids
        self.HASIDENT = False
    super(MSSQLExecutionContext, self).post_exec()

def malloc_varsize(self, typeid, length, size, itemsize, offset_to_length,
                   can_collect):
    if can_collect and self.bytes_malloced > self.bytes_malloced_threshold:
        self.collect()
    try:
        varsize = rarithmetic.ovfcheck(itemsize * length)
    except OverflowError:
        raise MemoryError
    # XXX also check for overflow on the various '+' below!
    if size > (2**63 - varsize):
        raise MemoryError('Size overflow')
    size += varsize
    size_gc_header = self.gcheaderbuilder.size_gc_header
    result = raw_malloc(size_gc_header + size)
    (result + size_gc_header + offset_to_length).signed[0] = length
    hdr = llmemory.cast_adr_to_ptr(result, self.HDRPTR)
    hdr.typeid = typeid << 1
    if not self.getfinalizer(typeid):
        hdr.next = self.malloced_objects
        self.malloced_objects = hdr
    else:
        hdr.next = self.malloced_objects_with_finalizer
        self.malloced_objects_with_finalizer = hdr
    self.bytes_malloced += raw_malloc_usage(size + size_gc_header)
    result += size_gc_header
    return llmemory.cast_adr_to_ptr(result, llmemory.GCREF)

def compute(self, name, grid=None, data=None, **kwargs):
    """Compute the quantity given by name on grid.

    Parameters
    ----------
    name : str
        Name of the quantity to compute.
    grid : Grid, optional
        Grid of coordinates to evaluate at. Defaults to the quadrature grid.

    Returns
    -------
    data : dict of ndarray
        Computed quantity and intermediate variables.

    """
    if name not in data_index:
        raise ValueError("Unrecognized value '{}'.".format(name))
    if grid is None:
        grid = QuadratureGrid(self.L, self.M, self.N, self.NFP)

    fun = getattr(compute_funs, data_index[name]["fun"])
    sig = signature(fun)

    inputs = {"data": data}
    for arg in sig.parameters.keys():
        if arg in arg_order:
            inputs[arg] = getattr(self, arg)
        elif arg == "R_transform":
            inputs[arg] = Transform(
                grid, self.R_basis, derivs=data_index[name]["R_derivs"]
            )
        elif arg == "Z_transform":
            inputs[arg] = Transform(
                grid, self.Z_basis, derivs=data_index[name]["R_derivs"]
            )
        elif arg == "L_transform":
            inputs[arg] = Transform(
                grid, self.L_basis, derivs=data_index[name]["L_derivs"]
            )
        elif arg == "B_transform":
            inputs[arg] = Transform(
                grid,
                DoubleFourierSeries(
                    M=2 * self.M, N=2 * self.N, sym=self.R_basis.sym, NFP=self.NFP
                ),
                derivs=0,
                build_pinv=True,
            )
        elif arg == "w_transform":
            inputs[arg] = Transform(
                grid,
                DoubleFourierSeries(
                    M=2 * self.M, N=2 * self.N, sym=self.Z_basis.sym, NFP=self.NFP
                ),
                derivs=1,
            )
        elif arg == "pressure":
            inputs[arg] = self.pressure.copy()
            inputs[arg].grid = grid
        elif arg == "iota":
            inputs[arg] = self.iota.copy()
            inputs[arg].grid = grid
        elif arg == "M_booz":
            inputs[arg] = kwargs.get("M_booz", None)
        elif arg == "N_booz":
            inputs[arg] = kwargs.get("N_booz", None)

    return fun(**inputs)

def __init__(self, file=None, chunks: dict = None, multiple=False):
    super().__init__()
    debug(f"Creating a new {get_slug(self)}")
    if file is not None:
        self.read_cmems(file, chunks, multiple)
    else:
        self.dataset = None
    debug(f"{get_slug(self)} initialised")

def parse_trade(self, trade, market=None):
    timestamp = None
    if 'Timestamp' in trade:
        timestamp = trade['Timestamp'] * 1000
    elif 'TimeStamp' in trade:
        timestamp = self.parse8601(trade['TimeStamp'])
    price = None
    cost = None
    if 'Price' in trade:
        price = trade['Price']
    elif 'Rate' in trade:
        price = trade['Rate']
    fee = None
    if 'Fee' in trade:
        fee = trade['Fee']
    elif 'FeeAmount' in trade:
        fee = trade['FeeAmount']
    return {
        'id': None,
        'info': trade,
        'timestamp': timestamp,
        'datetime': self.iso8601(timestamp),
        'symbol': market['symbol'],
        'type': None,
        'side': trade['Type'].lower(),
        'price': price,
        'cost': cost,
        'amount': trade['Amount'],
        'fee': fee,
    }

def _GenerateGradleFile(entry, generator, build_vars, jinja_processor):
  """Returns the data for a project's build.gradle."""
  deps_info = entry.DepsInfo()
  gradle = entry.Gradle()

  variables = {
      'sourceSetName': 'main',
      'depCompileName': 'compile',
  }
  if deps_info['type'] == 'android_apk':
    target_type = 'android_apk'
  elif deps_info['type'] == 'java_library':
    if deps_info['is_prebuilt'] or deps_info['gradle_treat_as_prebuilt']:
      return None
    elif deps_info['requires_android']:
      target_type = 'android_library'
    else:
      target_type = 'java_library'
  elif deps_info['type'] == 'java_binary':
    if gradle['main_class'] == 'org.chromium.testing.local.JunitTestMain':
      target_type = 'android_junit'
      variables['sourceSetName'] = 'test'
      variables['depCompileName'] = 'testCompile'
    else:
      target_type = 'java_binary'
      variables['main_class'] = gradle['main_class']
  else:
    return None

  variables['target_name'] = os.path.splitext(deps_info['name'])[0]
  variables['template_type'] = target_type
  variables['use_gradle_process_resources'] = (
      generator.use_gradle_process_resources)
  source_properties = _ReadPropertiesFile(
      _RebasePath(os.path.join(build_vars['android_sdk_build_tools'],
                               'source.properties')))
  variables['build_tools_version'] = source_properties['Pkg.Revision']
  variables['compile_sdk_version'] = (
      'android-%s' % build_vars['android_sdk_version'])
  variables['main'] = generator.Generate(entry)
  bootclasspath = gradle.get('bootclasspath')
  if bootclasspath:
    # Must use absolute path here.
    variables['bootclasspath'] = _RebasePath(bootclasspath)
  if entry.android_test_entry:
    variables['android_test'] = generator.Generate(
        entry.android_test_entry)
    for key, value in variables['android_test'].iteritems():
      if isinstance(value, list):
        variables['android_test'][key] = list(
            set(value) - set(variables['main'][key]))

  return jinja_processor.Render(
      _TemplatePath(target_type.split('_')[0]), variables)

def getch(self, inputs):
    if not inputs:
