def changes_between(
    model_type: Literal["FeatureFlag", "Person", "Insight"],
    previous: Optional[models.Model],
    current: Optional[models.Model],
) -> List[Change]:
    """
    Identifies changes between two models by comparing fields
    """
    changes: List[Change] = []

    if previous is None and current is None:
        # there are no changes between two things that don't exist
        return changes

    if previous is not None:
        fields = current._meta.fields if current is not None else []

        # Include tags in the fields assessed
        filtered_fields = [f.name for f in fields if f.name not in field_exclusions[model_type]]
        for field in filtered_fields:
            left = getattr(previous, field, None)
            right = getattr(current, field, None)

            if left is None and right is not None:
                changes.append(Change(type=model_type, field=field, action="created", after=right,))
            elif right is None and left is not None:
                changes.append(Change(type=model_type, field=field, action="deleted", before=left,))
            elif left != right:
                changes.append(Change(type=model_type, field=field, action="changed", before=left, after=right,))

    return changes

def localpath(self, url, ud, d):

    ud.proto = "rsync"
    if 'protocol' in ud.parm:
        ud.proto = ud.parm['protocol']

    ud.tag = "latest"
    if 'tag' in ud.parm:
        ud.tag = ud.parm['tag']

    ud.localfile = data.expand('git_%s%s_%s.tar.gz' % (ud.host, ud.path.replace('/', '.'), ud.tag), d)

    return os.path.join(data.getVar("DL_DIR", d, True), ud.localfile)

def getposts(basequery=None, pinned=False, showall=False, statuses=None):
    if not statuses:
        statuses = POSTSTATUS.LISTED

    if basequery is None:
        basequery = JobPost.query

    query = basequery.filter(JobPost.status.in_(statuses)).options(*JobPost._defercols)

    if showall:
        query = query.filter(JobPost.datetime > datetime.utcnow() - agelimit)
    else:
        if pinned:
            query = query.filter(
                db.or_(
                    db.and_(JobPost.pinned == True, JobPost.datetime > datetime.utcnow() - agelimit),
                    db.and_(JobPost.pinned == False, JobPost.datetime > datetime.utcnow() - newlimit)))  # NOQA
            )
        else:
            query = query.filter(JobPost.datetime > datetime.utcnow() - newlimit)

    if g.board and g.board.name != u'www':
        query = query.join(JobPost.postboards).filter(BoardJobPost.board == g.board)

    if pinned:
        if g.board:
            query = query.order_by(db.desc(BoardJobPost.pinned))
        else:
            query = query.order_by(db.desc(JobPost.pinned))

    return query.order_by(db.desc(JobPost.datetime))

def get_stream_dailymotion(plugin,
                           video_id,
                           download_mode=False):

    # TODO reactivate when youtubedl is fixed
    url_dailymotion = URL_DAILYMOTION_EMBED % video_id
    return get_stream_default(plugin, url_dailymotion, download_mode)
    if download_mode:
        return False
    url_dmotion = URL_DAILYMOTION_EMBED_2 % (video_id)
    resp = urlquick.get(url_dmotion, max_age=-1)
    json_parser = json.loads(resp.text)

    if "qualities" not in json_parser:
        plugin.notify('ERROR', plugin.localize(30716))

    all_datas_videos_path = []
    if "auto" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["auto"][0]["url"])
    if "144" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["144"][1]["url"])
    if "240" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["240"][1]["url"])
    if "380" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["380"][1]["url"])
    if "480" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["480"][1]["url"])
    if "720" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["720"][1]["url"])
    if "1080" in json_parser["qualities"]:
        all_datas_videos_path.append(json_parser["qualities"]["1080"][1]["url"])

    url_stream = ''
    for video_path in all_datas_videos_path:
        url_stream = video_path

    manifest = urlquick.get(url_stream, max_age=-1)
    lines = manifest.text.splitlines()
    inside_m3u8 = ''
    for k in range(0, len(lines) - 1):
        if 'RESOLUTION=' in lines[k]:
            inside_m3u8 = lines[k + 1]
    return inside_m3u8.split('#cell')[0]

