def _overlay_mask(image, mask):
    if image.ndim == 2:
        image = np.stack([image, image, image]).transpose((1, 2, 0))
    elif image.ndim != 3 or image.shape[2] != 3:
        raise ValueError('Image must be either grayscale (2D) or RGB (3D with 3 channels)')
    mask_overlay = np.zeros_like(image)
    mask_overlay[mask == 1] = [255, 0, 0]
    alpha = 0.6
    overlay = alpha * image + (1.0 - alpha) * mask_overlay
    return overlay.astype('uint8')

def send_email(config, entry, comment, comment_dir, comment_filename):
    """Send an email to the blog owner on a new comment

    @param config: configuration as parsed by Pyblosxom
    @type config: dictionary

    @param entry: a file entry
    @type config: dictionary

    @param comment: comment as generated by readComment
    @type comment: dictionary

    @param comment_dir: the comment directory
    @type comment_dir: string

    @param comment_filename: file name of current comment
    @type comment_filename: string
    """
    import smtplib
    try:
        from email.Utils import formatdate
    except ImportError:
        from rfc822 import formatdate

    author = escape_SMTP_commands(clean_author(comment['author']))
    description = escape_SMTP_commands(comment['description'])
    ipaddress = escape_SMTP_commands(comment.get('ipaddress', '?'))

    if comment.has_key('email'):
        email = comment['email']
    else:
        email = config['comment_smtp_from']

    try:
        server = smtplib.SMTP(config['comment_smtp_server'])
        curl = config['base_url']+'/'+entry['file_path']
        comment_dir = os.path.join(config['comment_dir'], entry['absolute_path'])

        message = []
        message.append("From: %s" % email)
        message.append("To: %s" % config["comment_smtp_to"])
        message.append("Date: %s" % formatdate(float(comment['pubDate'])))
        message.append("Subject: write back by %s" % author)
        message.append("")
        message.append("%s\n%s\n%s\n%s\n" % (description, ipaddress, comment_filename, curl))
        server.sendmail(from_addr=email,
                        to_addrs=config['comment_smtp_to'],
                        msg="\n".join(message))
        server.quit()
    except Exception as e:
        tools.log("Error sending mail: %s" % e)

def _build_log_files_from_dictionary(self, list_of_logs_in_dictionaries):
    loglist = {}
    for log in list_of_logs_in_dictionaries:
        try:
            loglist[log["name"]] = LogFile(
                log["maxdepth"], log["name"], log["timestamp"], log["binsize"], self.ip
            )
        except dateutil.parser.ParserError:
            logging.error(f"Could not parse timestamp for log {log['name']}, skipping this log file")
    return loglist

def __init__(self, *args):
    """
    Matrix can be constructed with values or a rule.

    >>> from sympy import Matrix, I
    >>> Matrix( ((1,2+I), (3,4)) ) #doctest:+NORMALIZE_WHITESPACE
    [1, 2 + I]
    [3,     4]
    >>> Matrix(2, 2, lambda i,j: (i+1)*j ) #doctest:+NORMALIZE_WHITESPACE
    [0, 1]
    [0, 2]

    """
    if len(args) == 3 and callable(args[2]):
        operation = args[2]
        self.rows = int(args[0])
        self.cols = int(args[1])
        self.mat = []
        for i in range(self.rows):
            for j in range(self.cols):
                self.mat.append(sympify(operation(i, j)))
    elif len(args)==3 and isinstance(args[2], (list, tuple)):
        self.rows=args[0]
        self.cols=args[1]
        mat = args[2]
        if len(mat) != self.rows*self.cols:
            raise MatrixError('List length should be equal to rows*columns')
        self.mat = map(lambda i: sympify(i), mat)
    elif len(args) == 1:
        mat = args[0]
        if isinstance(mat, Matrix):
            self.rows = mat.rows
            self.cols = mat.cols
            self.mat = mat[:]
            return
        elif hasattr(mat, "__array__"):
            arr = mat.__array__()
            if len(arr.shape) == 2:
                self.rows, self.cols = arr.shape[0], arr.shape[1]
                self.mat = map(lambda i: sympify(i), arr.ravel())
                return
            elif len(arr.shape) == 1:
                self.rows, self.cols = 1, arr.shape[0]
                self.mat = [0]*self.cols
                for i in xrange(len(arr)):
                    self.mat[i] = sympify(arr[i])
                return
            else:
                raise NotImplementedError("Sympy supports just 1D and 2D matrices")
        elif not isinstance(mat, (list, tuple)):
            raise TypeError("Matrix constructor doesn't accept %s as input" % str(type(mat)))
        self.rows = len(mat)
        if len(mat) != 0:
            if not isinstance(mat[0], (list, tuple)):
                self.cols = 1
                self.mat = map(lambda i: sympify(i), mat)
                return
            self.cols = len(mat[0])
        else:
            self.cols = 0
        self.mat = []
        for j in xrange(self.rows):
            assert len(mat[j])==self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))
    elif len(args) == 0:
        # Empty Matrix
        self.rows = self.cols = 0
        self.mat = []
    else:
        mat = args
        if not isinstance(mat[0], (list, tuple)):
            # make each element a singleton
            mat = [ [element] for element in mat ]
        warnings.warn("Deprecated constructor, use brackets: Matrix(%s)" % str(mat))
        self.rows=len(mat)
        self.cols=len(mat[0])
        self.mat=[]
        for j in xrange(self.rows):
            assert len(mat[j])==self.cols
            for i in xrange(self.cols):
                self.mat.append(sympify(mat[j][i]))

