def setAuthors(template, authors):
    """
    Add author information to the template document.

    Names and contact information for authors are added to each node with a
    C{class} attribute set to C{authors} and to the template head as C{link}
    nodes.

    @type template: A DOM Node or Document
    @param template: The output template which defines the presentation of the
    version information.

    @type authors: C{list} of two-tuples of C{str}
    @param authors: List of names and contact information for the authors of
    the input document.

    @return: C{None}
    """
    text = ''
    for name, href in authors:
        anchor = '<a href="%s">%s</a>' % (xml.sax.saxutils.quoteattr(href), xml.sax.saxutils.escape(name))
        if (name, href) == authors[-1]:
            if len(authors) == 1:
                text = anchor
            else:
                text += 'and ' + anchor
        else:
            text += anchor + ','

    childNodes = microdom.parseString('<span>' + text +'</span>').childNodes

    for node in domhelpers.findElementsWithAttribute(template,
                                                     "class", 'authors'):
        node.childNodes.extend(childNodes)

    head = domhelpers.findNodesNamed(template, 'head')[0]
    authors = [microdom.parseString('<link rel="author" href="%s" title="%s"/>'
                                    % (xml.sax.saxutils.quoteattr(href), xml.sax.saxutils.escape(name))).childNodes[0]
               for name, href in authors]
    head.childNodes.extend(authors)

def lookup_class(
    kind: str, apiVersion: Optional[str] = None, default: Optional[str] = "__main__"
) -> object:
    if kind in _ClassRegistry:
        return _ClassRegistry[kind]
    elif kind in _shortNameRegistry:
        className = _shortNameRegistry[kind]
    else:
        className = kind
    try:
        klass = load_class(className, default)
    except ImportError:
        klass = None

    if klass:
        register_class(className, klass)
    return klass

def good_friday_unless_christmas_nye_friday(dt):
    """
    Good Friday is a valid trading day if Christmas Day or New Years Day fall
    on a Friday.
    """
    year = dt.year
    christmas_weekday = Christmas.observance(
        pd.Timestamp(year, 12, 25)
    ).weekday()
    nyd_weekday = USNewYearsDay.observance(
        pd.Timestamp(year, 1, 1)
    ).weekday()
    if christmas_weekday != 4 and nyd_weekday != 4:
        return GoodFriday._apply_rule(dt)
    else:
        return pd.NaT

def execute(self, context):

    # get list of selected objects
    obj_list = context.selected_objects
    if not obj_list:
        self.report({'ERROR'}, "No objects selected")
        return {'CANCELLED'}

    # gets the list of materials (without repetition) from selected
    mat_list = util.materialsFromObj(obj_list)
    if not mat_list:
        self.report({'ERROR'}, "No materials found on selected objects")
        return {'CANCELLED'}

    # check if linked material exists
    engine = context.scene.render.engine
    count = 0

    for mat in mat_list:
        passes = generate.get_textures(mat)
        if not self.useExtraMaps:
            for pass_name in passes:
                if pass_name != "diffuse":
                    passes[pass_name] = None
        if self.autoFindMissingTextures:
            for pass_name in passes:
                res = generate.replace_missing_texture(passes[pass_name])
                if res>0:
                    mat["texture_swapped"] = True  # used to apply saturation
        if mat.is_linked:
            # Handle linked materials differently
            res = generate.handle_linked_material(mat, passes)
            if res==0:
                count+=1
        elif engine == 'BLENDER_RENDER' or engine == 'BLENDER_GAME':
            res = generate.matprep_internal(mat, passes,
                self.useReflections, self.makeSolid)
            if res==0:
                count+=1
            if self.animateTextures:
                sequences.animate_single_material(
                    mat, context.scene.render.engine)
        elif engine == 'CYCLES' or engine == 'BLENDER_EEVEE':
            res = generate.matprep_cycles(mat, passes, self.useReflections,
                self.usePrincipledShader, self.makeSolid)
            if res==0:
                count+=1
            if self.animateTextures:
                sequences.animate_single_material(
                    mat, context.scene.render.engine)
        else:
            self.report({'ERROR'},"Only blender internal or cycles supported")
            return {'CANCELLED'}

    if self.combineMaterials is True:
        bpy.ops.mcprep.combine_materials(selection_only=True, skipUsage=True)
    if self.improveUiSettings:
        bpy.ops.mcprep.improve_ui()
    self.report({"INFO"},"Modified "+str(count)+" materials")
    self.track_param = context.scene.render.engine
    self.track_exporter = generate.detect_form(mat_list)
    return {'FINISHED'}

def get_metric(name):

    try:
        return METRIC_REGISTRY[name]
    except KeyError:
        logging.warning(
            f"Could not find registered metric '{name}' in lm-eval, searching in HF Evaluate library..."
        )
        try:
            metric_object = evaluate.load(name)
            return metric_object.compute
        except Exception:
            eval_logger.error(
                "{} not found in the evaluate library!".format(name),
                "Please check https://huggingface.co/evaluate-metric",
            )

def add_image(self, can_remove = True):
    '''Add an image to be measured'''
    class ImageSettings(cps.SettingGroup):
        '''Settings describing an image to be measured'''
        def __init__(self, images):
            super().__init__()
            self.key = uuid.uuid4()
            self.image_name = cps.ImageNameSubscriber(
                "Select the input image", "None")
            if can_remove:
                def remove(images=images, key = self.key):
                    index = [x.key for x in images].index(key)
                    del images[index]
                self.remove_button = cps.DoSomething("Remove above image",
                                                     "Remove", remove)
        def settings(self):
            '''Return the settings that should be saved in the pipeline'''
            return [self.image_name]

        def visible_settings(self):
            '''Return the settings that should be displayed'''
            if can_remove:
                return [self.image_name, self.remove_button]
            else:
                return [self.image_name]
    self.images.append(ImageSettings(self.images))

def get_package_members(
    package: db_models.Package = Depends(get_package_or_fail),
    dao: Dao = Depends(get_dao),
):

    member_list = dao.get_package_members(package.channel.name, package.name)

    for member in member_list:
        # force loading of profile before changing attributes to prevent sqlalchemy errors.
        member.user.profile
        # Removed abuse of db models for this.
        setattr(member.user, "id", str(uuid.UUID(bytes=member.user.id)))

    return member_list

def set_doc_variables(item, job, params):
    change = item.change
    doc_subpath = ''

    # ref-updated
    if hasattr(change, 'ref'):
        tag = re.match(r'^refs/tags/(.*)', change.ref)
        if tag:
            # For jobs from Zuul "publish" pipeline,
            # using the "zuul-post" trigger in their Jenkins job.
            # Example value 'refs/tags/v1.2.3' -> 'v1.2.3'
            doc_subpath = tag.group(1)
        else:
            # Branch: 'master'
            doc_subpath = change.ref
    # Changes
    elif hasattr(change, 'refspec'):
        doc_subpath = change.branch

    if doc_subpath:
        params['DOC_SUBPATH'] = doc_subpath

    if 'ZUUL_PROJECT' in params:
        raw_project = params['ZUUL_PROJECT']
        if raw_project in doc_destination:
            # custom names
            raw_project = doc_destination[raw_project]
        elif raw_project.startswith('mediawiki/extensions/'):
            # For MediaWiki extension repos
            raw_project = raw_project.split('/')[-1]

        # Normalize the project name by removing /'s
        params['DOC_PROJECT'] = raw_project.replace('/', '-')

def getWeaponSystemData(fit):
    weaponSystems = []
    groups = {}
    defaultSpoolValue = 1
    spoolOptions = SpoolOptions(SpoolType.SCALE, defaultSpoolValue, False)
    for mod in fit.modules:
        if mod.getDps(spoolOptions=spoolOptions).total > 0:
            keystr = str(mod.itemID) + "-" + str(mod.chargeID)
            if keystr in groups:
                groups[keystr][1] += 1
            else:
                groups[keystr] = [mod, 1]
    for wepGroup in groups.values():
        stats = wepGroup[0]
        n = wepGroup[1]
        tracking = 0
        maxVelocity = 0
        explosionDelay = 0
        damageReductionFactor = 0
        explosionRadius = 0
        explosionVelocity = 0
        aoeFieldRange = 0
        typeing = 'None'
        if stats.charge:
            name = stats.item.name + ", " + stats.charge.name
        else:
            name = stats.item.name
        if stats.hardpoint == Hardpoint.TURRET:
            tracking = stats.getModifiedItemAttr("trackingSpeed")
            typeing = "Turret"
        elif stats.hardpoint == Hardpoint.MISSILE or "Bomb Launcher" in stats.item.name:
            maxVelocity = stats.getModifiedChargeAttr("maxVelocity")
            explosionDelay = stats.getModifiedChargeAttr("explosionDelay")
            damageReductionFactor = stats.getModifiedChargeAttr("aoeDamageReductionFactor")
            explosionRadius = stats.getModifiedChargeAttr("aoeCloudSize")
            explosionVelocity = stats.getModifiedChargeAttr("aoeVelocity")
            typeing = "Missile"
        elif stats.hardpoint == Hardpoint.NONE:
            aoeFieldRange = stats.getModifiedItemAttr("empFieldRange")
            typeing = "SmartBomb"
        if stats.item.group.name == 'Super Weapon' and stats.maxRange is None:
            maxRange = 300000
        else:
            maxRange = stats.maxRange
        statDict = {
            "dps": stats.getDps(spoolOptions=spoolOptions).total * n, "capUse": stats.capUse * n, "falloff": stats.falloff,
            "type": typeing, "name": name, "optimal": maxRange,
            "numCharges": stats.numCharges, "numShots": stats.numShots, "reloadTime": stats.reloadTime,
            "cycleTime": stats.cycleTime, "volley": stats.getVolley(spoolOptions=spoolOptions).total * n, "tracking": tracking,
            "maxVelocity": maxVelocity, "explosionDelay": explosionDelay, "damageReductionFactor": damageReductionFactor,
            "explosionRadius": explosionRadius, "explosionVelocity": explosionVelocity, "aoeFieldRange": aoeFieldRange,
            "damageMultiplierBonusMax": stats.getModifiedItemAttr("damageMultiplierBonusMax"),
            "damageMultiplierBonusPerCycle": stats.getModifiedItemAttr("damageMultiplierBonusPerCycle")
        }
        weaponSystems.append(statDict)
    for drone in fit.drones:
        if drone.getDps().total > 0 and drone.amountActive > 0:
            droneAttr = drone.getModifiedItemAttr
            newTracking = droneAttr("trackingSpeed") / (droneAttr("optimalSigRadius") / 40000)
            statDict = {
                "dps": drone.getDps().total, "cycleTime": drone.cycleTime, "type": "Drone",
                "optimal": drone.maxRange, "name": drone.item.name, "falloff": drone.falloff,
                "maxSpeed": droneAttr("maxVelocity"), "tracking": newTracking,
                "volley": drone.getVolley().total
            }
            weaponSystems.append(statDict)
    for fighter in fit.fighters:
        if fighter.getDps().total > 0 and fighter.amountActive > 0:
            fighterAttr = fighter.getModifiedItemAttr
            abilities = []
            if "fighterAbilityAttackMissileDamageEM" in fighter.item.attributes.keys():
                baseRef = "fighterAbilityAttackMissile"
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            if "fighterAbilityMissilesDamageEM" in fighter.item.attributes.keys():
                baseRef = "fighterAbilityMissiles"
                ability = EfsPort.getFighterAbilityData(fighterAttr, fighter, baseRef)
                abilities.append(ability)
            statDict = {
                "dps": fighter.getDps().total, "type": "Fighter", "name": fighter.item.name,
                "maxSpeed": fighterAttr("maxVelocity"), "abilities": abilities,
                "ehp": fighterAttr("shieldCapacity") / 0.8875 * fighter.amountActive,
                "volley": fighter.getVolley().total, "signatureRadius": fighterAttr("signatureRadius")
            }
            weaponSystems.append(statDict)
    return weaponSystems

