def on_task_metainfo(self, task, config):
    # Take a snapshot of any new entries' states before metainfo event in case we have to store them to backlog
    for entry in task.entries:
        snapshot = entry.snapshots.get('after_input')
        if snapshot:
            continue
        entry.take_snapshot('after_input')

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        return None
    else:
        return self._generator.next()

def update_tool(
    db: Session,
    tool: Tool,
    patch_tool: t.Union[CreateTool, PatchToolDockerimage],
) -> Tool:
    if isinstance(patch_tool, CreateTool):
        tool.name = patch_tool.name
    elif patch_tool.persistent:
        tool.docker_image_template = patch_tool.persistent
        tool.readonly_image = True
    db.add(tool)
    db.commit()
    return tool

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            job, orm_job = self._get_job_and_orm_job(job_id, session)
            job = copy(job)
            if state is not None:
                job.state = state
            for kwarg in kwargs:
                setattr(job, kwarg, kwargs[kwarg])
            orm_job.obj = job
            session.add(orm_job)
            return job, orm_job
        except JobNotFound:
            if state:
                logger.error(
                    "Tried to update job with id {} with state {} but it was not found".format(
                        job_id, state
                    )
                )
            else:
                logger.error(
                    "Tried to update job with id {} but it was not found".format(
                        job_id
                    )
                )

