def get_sequence(self, name):
    """
    Returns the saved Pulse_Sequence object by name without setting it as current sequence
    """
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise FileNotFoundError(f'Error: No sequence with name "{name}" in saved sequences.')
    return sequence

def _check_chunk_length(self, cursor, value):
    if self.cluster.version() >= '3.0':
        table_metadata = self.cluster.metadata.keyspaces['ks'].tables['test_table']
    else:
        table_metadata = self.cluster.metadata.keyspaces['ks'].tables['test_table']
    params = table_metadata.options

    assert 'sstable_compression' in params, "Looking for a row with the string 'sstable_compression', but could not find it."

    chunk_length = int(params['chunk_length_kb'])

    assert chunk_length == value, "Expected chunk_length: %s.  We got: %s" % (value, chunk_length)

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated_types = ''  # Added templated_types
    suffix = '%s %s%s %s' % (modifiers, self.type_name, syntax, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b"\x00" * 0x43)
    if aeskeytype - 1 > 4 or (1 << (aeskeytype - 1) & 0x17) == 0:
        return 0xF2000002
    if requestedlen > 0xFF or (requestedlen << 28) & 0xFFFFFFFF:
        return 0xF2000003
    if 0x0 >= len(key) > 0x20:
        return 0xF2000003
    bufferlen = len(salt) + 3 + len(key)
    iterlength = (requestedlen + 0xF) >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack("<I", 8 * requestedlen)
    # Verify buffer structure
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0x0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 0x108, 4):
                result.extend(pack("<I", field))
    return result

def decrypt(self):
    encryption_context = self.parameters.get("EncryptionContext")
    original_encryption_context = self.parameters.get("OriginalEncryptionContext")
    if encryption_context != original_encryption_context:
        raise ValueError("EncryptionContext does not match. Refusing to decode.")

    value = self.parameters.get("CiphertextBlob")
    try:
        return json.dumps({"Plaintext": base64.b64decode(value).decode("utf-8"), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({"Plaintext": value})

def _decode_to(cls: Type[T], raw_rlp: RLP) -> T:
    """
    Decode the rlp structure in `encoded_data` to an object of type `cls`.
    `cls` can be a `Bytes` subclass, a dataclass, `Uint`, `U256`,
    `Tuple[cls, ...]`, `Tuple[cls1, cls2]` or `Union[Bytes, cls]`.

    Parameters
    ----------
    cls: `Type[T]`
        The type to decode to.
    raw_rlp :
        A decode rlp structure.

    Returns
    -------
    decoded_data : `T`
        Object decoded from `encoded_data`.
    """
    if isinstance(cls, type(Tuple[Uint, ...])) and cls._name == "Tuple":  # type: ignore # noqa: E501
        ensure(type(raw_rlp) == list, RLPDecodingError)
        if cls.__args__[1] == ...:  # type: ignore
            args = []
            for raw_item in raw_rlp:
                args.append(_decode_to(cls.__args__[0], raw_item))  # type: ignore # noqa: E501
            return tuple(args)  # type: ignore
        else:
            args = []
            for (t, raw_item) in zip(cls.__args__, raw_rlp):  # type: ignore
                args.append(_decode_to(t, raw_item))
            return tuple(args)  # type: ignore
    elif cls == Union[Bytes0, Bytes20]:
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        if len(raw_rlp) == 0:
            return Bytes0()  # type: ignore
        elif len(raw_rlp) == 20:
            return Bytes20(raw_rlp)  # type: ignore
        else:
            raise RLPDecodingError(
                "RLP Decoding to type {} is not supported".format(cls)
            )
    elif isinstance(cls, type(List[Bytes])) and cls._name == "List":  # type: ignore # noqa: E501
        ensure(type(raw_rlp) == list, RLPDecodingError)
        items = []
        for raw_item in raw_rlp:
            items.append(_decode_to(cls.__args__[0], raw_item))  # type: ignore
        return items  # type: ignore
    elif isinstance(cls, type(Union[Bytes, List[Bytes]])) and cls.__origin__ == Union:  # type: ignore # noqa: E501
        if len(cls.__args__) != 2 or Bytes not in cls.__args__:  # type: ignore
            raise RLPDecodingError(
                "RLP Decoding to type {} is not supported".format(cls)
            )
        if isinstance(raw_rlp, Bytes):
            return raw_rlp  # type: ignore
        elif cls.__args__[0] == Bytes:  # type: ignore
            return _decode_to(cls.__args__[1], raw_rlp)  # type: ignore
        else:
            return _decode_to(cls.__args__[0], raw_rlp)  # type: ignore
    elif issubclass(cls, bool):
        if raw_rlp == b"\x01":
            return cls(True)  # type: ignore
        elif raw_rlp == b"":
            return cls(False)  # type: ignore
        else:
            raise TypeError("Cannot decode {} as {}".format(raw_rlp, cls))
    elif issubclass(cls, Bytes):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return raw_rlp
    elif issubclass(cls, (Uint, U256, Uint64)):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return cls.from_be_bytes(raw_rlp)  # type: ignore
    elif is_dataclass(cls):
        ensure(type(raw_rlp) == list, RLPDecodingError)
        assert isinstance(raw_rlp, list)
        if len(raw_rlp) != len(fields(cls)):
            raise RLPDecodingError(
                "RLP Decoding to type {} is not supported due to length mismatch".format(cls)
            )
        args = []
        for (field, rlp_item) in zip(fields(cls), raw_rlp):
            args.append(_decode_to(field.type, rlp_item))
        return cls(*args)
    else:
        raise RLPDecodingError(
            "RLP Decoding to type {} is not supported".format(cls)
        )

def primary_key(self):
    from kart.working_copy import gpkg_adapter

    with self.engine.connect() as conn:
        return gpkg_adapter.pk(conn, self.table)

def get_observation1(
    first_metric_name: str = "a",
    second_metric_name: str = "b",
) -> Observation:
    return Observation(
        features=ObservationFeatures(
            parameters={"x": 2.0, "y": 10.0}, trial_index=np.int64(0)
        ),
        data=ObservationData(
            means=np.array([2.0, 4.0]),
            covariance=np.array([[1.0, 2.0], [3.0, 4.0]]),
            metric_names=[first_metric_name, second_metric_name],
        ),
        arm_name="1_1",
    )

def process_dependencies(self, task, deplist, uowcommit, delete = False):
    #print self.mapper.mapped_table.name + " " + self.key + " " + repr(len(deplist)) + " process_dep isdelete " + repr(delete) + " direction " + repr(self.direction)
    if delete:
        # head object is being deleted, and we manage its list of child objects
        # the child objects have to have their foreign key to the parent set to NULL

        # Implementing delete cascade
        for obj in deplist:
            childlist = self.get_object_dependencies(obj, uowcommit, passive=self.passive_deletes)
            if childlist is not None:
                for child in childlist.deleted_items():
                    if child is not None and childlist.hasparent(child) is False:
                        self._synchronize(obj, child, None, True, uowcommit)
                        self._conditional_post_update(child, uowcommit, [obj])
                for child in childlist.unchanged_items():
                    if child is not None:
                        self._synchronize(obj, child, None, True, uowcommit)
                        self._conditional_post_update(child, uowcommit, [obj])
    else:
        for obj in deplist:
            childlist = self.get_object_dependencies(obj, uowcommit, passive=True)
            if childlist is not None:
                for child in childlist.added_items():
                    self._synchronize(obj, child, None, False, uowcommit)
                    self._conditional_post_update(child, uowcommit, [obj])
                for child in childlist.deleted_items():
                    if not self.cascade.delete_orphan and not self._get_instrumented_attribute().hasparent(child):
                        self._synchronize(obj, child, None, True, uowcommit)

def dict_for_mongo(_dict):
    """Encode all keys in `_dict` for MongoDB."""
    for key, value in _dict.items():
        if _is_invalid_for_mongo(key):
            del _dict[key]
            key = _encode_for_mongo(key)

        if isinstance(value, list):
            _dict[key] = [dict_for_mongo(obj) if isinstance(obj, dict) else obj
                          for obj in value]
        elif isinstance(value, dict):
            _dict[key] = dict_for_mongo(value)
        else:
            _dict[key] = str(value)  # Generic conversion to string for non-dict values

    return _dict

def del_var_from_env(self, varname):
    decoded_qs = [
        (key, value) for key, value in self.request.args.items(multi=True) if key != varname
    ]
    self.request.environ['QUERY_STRING'] = urllib.urlencode(decoded_qs)
    self.request.__dict__.pop('args', None)
    self.request.__dict__.pop('values', None)
    try:
        werkzeug.datastructures.MultiDict.pop(self.request.form, varname)
    except KeyError:
        pass

def append_changelog_changes_collections(builder: RstBuilder,
                                         changelog_entry: ChangelogEntry,
                                         is_last: bool) -> PluginDataT:
    result: PluginDataT = []

    if changelog_entry.changed_collections:
        if is_last:
            builder.add_section('Included Collections', 1)
        else:
            builder.add_section('Changed Collections', 1)
        for (
                collector, collection_version, prev_collection_version
        ) in changelog_entry.changed_collections:
            if is_last:
                msg = f"{collector.collection} with version {collection_version}."
                if prev_collection_version is not None:
                    msg += f" This was upgraded from version {prev_collection_version}."
            else:
                if prev_collection_version is None:
                    msg = f"{collector.collection} was upgraded to version {collection_version}."
                else:
                    msg = f"{collector.collection} was upgraded from"
                    msg += f" version {prev_collection_version} to version {collection_version}."
            msg += "\n"
            changelog = collector.changelog
            if changelog:
                release_entries = changelog.generator.collect(
                    squash=True,
                    after_version=prev_collection_version,
                    until_version=collection_version)
                if not release_entries:
                    msg += "The collection did not have a changelog in this version."
                elif release_entries[0].empty:
                    msg += "There are no changes recorded in the changelog."
                else:
                    result.append((
                        collector.collection,
                        f"{collector.collection}.",
                        changelog.generator,
                        release_entries[0]))
                    msg += "The changes are reported in the combined changelog below."
            else:
                msg += "Unfortunately, this collection does not provide changelog data in a format "
                msg += "that can be processed by the changelog generator."
                msg += f" For more details, visit the changelog: {collector.changelog_url}"

            builder.add_list_item(msg)
        builder.add_raw_rst('')

    return result

def from_dist(cls, dist, dependency_links, find_tags=False):
    location = os.path.normcase(os.path.abspath(dist.location))
    comments = []
    from pip.vcs import vcs, get_src_requirement
    if vcs.get_backend_name(location):
        editable = True
        try:
            req = get_src_requirement(dist, location, find_tags)
        except InstallationError as exc:
            logger.warn(
                "Error when trying to get requirement for VCS system %s, "
                "falling back to uneditable format" % exc
            )
            req = None
        if req is None:
            logger.warn(
                'Could not determine repository location of %s' % location
            )
            comments.append(
                '## !! Could not determine repository location'
            )
            req = dist.as_requirement()
            editable = False
    else:
        editable = False
        req = dist.as_requirement()
        specs = req.specs
        assert len(specs) == 1 and specs[0][0] == '=='
        version = specs[0][1]
        ver_match = cls._rev_re.search(version)
        date_match = cls._date_re.search(version)
        if ver_match or date_match:
            svn_backend = vcs.get_backend('svn')
            if svn_backend:
                svn_location = svn_backend().get_location(
                    dist,
                    dependency_links,
                )
            if not svn_location:
                logger.warn(
                    'Warning: cannot find svn location for %s' % req)
                comments.append(
                    '## !! Could not determine repository location'
                )
            else:
                comments.append(
                    '# Installing as editable to satisfy requirement %s:' %
                    req
                )
                if ver_match:
                    rev = ver_match.group(1)
                else:
                    rev = '{%s}' % date_match.group(1)
                editable = True
                req = '%s@%s#egg=%s' % (
                    svn_location,
                    rev,
                    cls.egg_name(dist)
                )
    return cls(dist.project_name, req, editable, comments)

def mbox_uuid(self):
    if self.mbox_wrapper is None:
        raise ValueError("mbox_wrapper is None")
    return self.mbox_wrapper.uuid

def method (self, methodId, objId, className,
            methodName, args=None, packageName="qpid"):
  codec = Codec (StringIO (), self.spec);
  codec.encode_long     (methodId)
  codec.encode_longlong (objId)
  codec.encode_shortstr (self.rqname)

  # Encode args according to schema
  if args is not None:
    for key, value in args.items():
      if isinstance(value, str):
        codec.encode_longstr(value)
      elif isinstance(value, int):
        codec.encode_long(value)

  if methodName == "echo":
    codec.encode_long (args["sequence"])
    codec.encode_longstr (args["body"])

  msg = Content (codec.stream.getvalue ())
  msg["content_type"] = "application/octet-stream"
  msg["routing_key"]  = "method." + packageName + "." + className + "." + methodName
  msg["reply_to"]     = self.spec.struct ("reply_to")
  self.channel.message_transfer (destination="qpid.management", content=msg)
